package web

// client_parity_test.go verifies that client configs (URIs / .conf) generated by
// buildClientURI / buildAWGClientConf / buildConnectionLink actually carry the
// server-side credentials (public key, short id, uuid, port, SNI, transport)
// that the server config is built from. This is the "client config must match the
// server config" parity check — guards against the class of bug where the UI
// hallucinates a client link whose keys don't correspond to the server inbound.
//
// We test the link builders in isolation (no SSH / no remote apply): we feed in
// known server-side values and assert they appear verbatim in the produced link.

import (
	"encoding/base64"
	"net/url"
	"strings"
	"testing"

	"github.com/alexeylcp/angry-box/internal/chain"
	"github.com/alexeylcp/angry-box/internal/domain/model"
)

func initDefaultProfile(t *testing.T) {
	t.Helper()
	chain.SetDefaultProfile("maximum_stealth_2026")
}

// mustContain fails the test if sub is not in s.
func mustContain(t *testing.T, s, sub, label string) {
	t.Helper()
	if !strings.Contains(s, sub) {
		t.Errorf("%s: link missing %q\nlink: %s", label, sub, s)
	}
}

// mustNotContain fails the test if sub IS in s (used to catch placeholder/garbage).
func mustNotContain(t *testing.T, s, sub, label string) {
	t.Helper()
	if strings.Contains(s, sub) {
		t.Errorf("%s: link unexpectedly contains %q\nlink: %s", label, sub, s)
	}
}

// ---- AWG ----

func TestClientLink_AWG_ChainCarriesServerPublicKey(t *testing.T) {
	initDefaultProfile(t)
	// Server side stores the entry node's AWG public key in chain.AWGEntryServerPub.
	// buildConnectionLink must surface that exact key in the client link.
	c := &model.Chain{
		Name:              "awg-chain",
		UserProtocol:      model.UserProtocolAWG,
		AWGEntryServerPub: "SERVERPUB_BASE64_43chars___________",
		Nodes:             []model.ChainNode{{ID: "n1", Addr: "203.0.113.7:22"}},
	}
	link := buildConnectionLink(c, &model.User{ID: "u1"})
	mustContain(t, link, "203.0.113.7", "AWG chain IP")
	mustContain(t, link, "SERVERPUB_BASE64_43chars___________", "AWG server public key")
	mustContain(t, link, "awg://", "AWG scheme")
	// Must NOT fall back to a tun/direct placeholder when a real key is present.
	mustNotContain(t, link, "10.8.0.", "AWG chain link (should be URI, not .conf)")
}

func TestClientLink_AWG_StandaloneConfMatchesServer(t *testing.T) {
	initDefaultProfile(t)
	// A standalone AWG inbound stores ServerPubKey + an AWGClientPriv on the node.
	// The client .conf must carry the SAME ServerPubKey in [Peer]PublicKey.
	ib := model.NodeInbound{
		Protocol:      "awg",
		Port:          51820,
		ServerPubKey:  "PEER_PUBKEY_BASE64_43chars__________",
		AWGClientPriv: "CLIENT_PRIVKEY_BASE64_43chars________",
		AWGClientPub:  "CLIENT_PUBKEY_BASE64_43chars_________",
	}
	link := buildStandaloneLink("203.0.113.7", ib, &model.User{ID: "u1"})
	mustContain(t, link, "[Interface]", "AWG .conf interface section")
	mustContain(t, link, "CLIENT_PRIVKEY_BASE64_43chars________", "AWG client private key")
	mustContain(t, link, "PEER_PUBKEY_BASE64_43chars__________", "AWG server public key parity")
	mustContain(t, link, "203.0.113.7:51820", "AWG endpoint (ip:port parity)")
	mustContain(t, link, "Jc = ", "AWG .conf amnezia Jc")
}

// ---- TUIC ----

func TestClientLink_TUIC_ChainCarriesUUIDAndPassword(t *testing.T) {
	initDefaultProfile(t)
	// Server-side TUIC inbound uses TUICEntryUserUUID/Password; the client link
	// must carry the SAME uuid:password so the client authenticates.
	c := &model.Chain{
		Name:                 "tuic-chain",
		UserProtocol:         model.UserProtocolTUIC,
		TUICEntryUserUUID:    "11111111-2222-3333-4444-555555555555",
		TUICEntryUserPassword: "tuic-pass-xyz",
		Nodes:                []model.ChainNode{{ID: "n1", Addr: "203.0.113.7:22"}},
	}
	link := buildConnectionLink(c, &model.User{ID: "u1"})
	mustContain(t, link, "tuic://", "TUIC scheme")
	mustContain(t, link, "11111111-2222-3333-4444-555555555555", "TUIC uuid parity")
	mustContain(t, link, "tuic-pass-xyz", "TUIC password parity")
	mustContain(t, link, "203.0.113.7:8443", "TUIC endpoint parity")
}

// ---- VLESS REALITY ----

func TestClientLink_VLESSReality_StandaloneParity(t *testing.T) {
	initDefaultProfile(t)
	// Server inbound stores Reality public key (ServerPubKey) + ShortID.
	ib := model.NodeInbound{
		Protocol:      "vless-reality",
		Port:          443,
		UUID:          "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee",
		ServerPubKey:  "REALITY_PUBKEY_BASE64URL_43chars_____",
		ShortID:       "1a2b3c4d",
	}
	link := buildStandaloneLink("203.0.113.7", ib, &model.User{ID: "u1"})
	mustContain(t, link, "vless://", "VLESS scheme")
	mustContain(t, link, "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee", "VLESS uuid parity")
	mustContain(t, link, "REALITY_PUBKEY_BASE64URL_43chars_____", "Reality public key parity")
	mustContain(t, link, "pbk=REALITY_PUBKEY_BASE64URL_43chars_____", "Reality pbk param")
	mustContain(t, link, "sid=1a2b3c4d", "Reality short id parity")
	mustContain(t, link, "203.0.113.7:443", "VLESS endpoint parity")
	mustContain(t, link, "security=reality", "Reality security")
	mustContain(t, link, "flow=xtls-rprx-vision", "Reality flow")
}

// ---- VLESS REALITY+XHTTP ----

func TestClientLink_VLESSRealityXHTTP_UsesServerSNI(t *testing.T) {
	initDefaultProfile(t)
	ib := model.NodeInbound{
		Protocol:     "vless-reality-xhttp",
		Port:         443,
		UUID:         "aaaa1111-bbbb-cccc-dddd-eeeeeeeeeeee",
		ServerPubKey: "RXHTTP_PUBKEY_BASE64URL_43chars______",
		ShortID:      "deadbeef",
	}
	link := buildStandaloneLink("203.0.113.7", ib, &model.User{ID: "u1"})
	mustContain(t, link, "vless://", "scheme")
	mustContain(t, link, "type=xhttp", "xhttp transport")
	mustContain(t, link, "security=reality", "reality security")
	mustContain(t, link, "RXHTTP_PUBKEY_BASE64URL_43chars______", "Reality pubkey parity")
	mustContain(t, link, "pbk=RXHTTP_PUBKEY_BASE64URL_43chars______", "pbk param")
	mustContain(t, link, "sid=deadbeef", "short id parity")
	mustContain(t, link, "mode=packet-up", "xhttp packet-up mode")
	// SNI must come from the active preset (not a hardcoded fallback in the link
	// when the preset defines one).
	preset := chain.GetDefaultPreset()
	if preset.Reality != nil && len(preset.Reality.ServerNames) > 0 {
		mustContain(t, link, url.QueryEscape(preset.Reality.ServerNames[0]), "preset SNI parity")
	}
}

