// ---- MTProxy ----

func TestClientLink_MTProxy_StandaloneParity(t *testing.T) {
	initDefaultProfile(t)
	ib := model.NodeInbound{
		Protocol: "mtproxy",
		Port:     443,
		UUID:     "0123456789abcdef0123456789abcdef",
	}
	link := buildStandaloneLink("203.0.113.7", ib, &model.User{ID: "u1"})
	mustContain(t, link, "tg://proxy", "MTProxy scheme")
	mustContain(t, link, "203.0.113.7", "MTProxy server parity")
	mustContain(t, link, "443", "MTProxy port parity")
	// Secret must be the full ee+secret+hex(domain) form, not just the raw secret.
	mustContain(t, link, "ee0123456789abcdef0123456789abcdef", "MTProxy full secret (ee-prefixed)")
}

// ---- VMess ----

func TestClientLink_VMess_StandaloneParity(t *testing.T) {
	initDefaultProfile(t)
	ib := model.NodeInbound{
		Protocol: "vmess",
		Port:     443,
		UUID:     "vmess-uuid-1234",
	}
	link := buildStandaloneLink("203.0.113.7", ib, &model.User{ID: "u1"})
	mustContain(t, link, "vmess://", "VMess scheme")
	// VMess link = base64(JSON{v,ps,add,port,id,aid,net,type,tls}). Decode the
	// payload and assert the server-side uuid + ip + port are embedded.
	payload := strings.TrimPrefix(link, "vmess://")
	dec, err := base64.StdEncoding.DecodeString(payload)
	if err != nil {
		t.Fatalf("vmess payload not valid base64: %v\nlink: %s", err, link)
	}
	body := string(dec)
	mustContain(t, body, `"add":"203.0.113.7"`, "VMess add (ip) parity")
	mustContain(t, body, `"port":"443"`, "VMess port parity")
	mustContain(t, body, `"id":"vmess-uuid-1234"`, "VMess uuid parity")
	mustContain(t, body, `"v":"2"`, "VMess version")
}

// ---- Empty/garbage guard ----

func TestClientLink_NoPlaceholderWhenFieldsPresent(t *testing.T) {
	initDefaultProfile(t)
	// If a real public key is supplied, the link must NEVER contain the
	// "fake/tun/direct" fallback marker that the v0.1.0 refactor removed.
	ib := model.NodeInbound{
		Protocol:     "vless-reality",
		Port:         443,
		UUID:         "u1",
		ServerPubKey: "REALPUB",
		ShortID:      "abcd1234",
	}
	link := buildStandaloneLink("203.0.113.7", ib, &model.User{ID: "u1"})
	mustNotContain(t, link, "fake", "no fake marker")
	mustNotContain(t, link, "placeholder", "no placeholder marker")
	mustNotContain(t, link, "TODO", "no TODO marker")
}